"""Build mixed supervision with separate checkpoint-selection and final sets."""
import json
from pathlib import Path
ROOT=Path(__file__).parent
SYSTEM='Составь задачу Jira на русском. Верни JSON summary, description, questions. Сохрани все согласованные требования и точные границы. В questions включи только оставшиеся открытые вопросы.'

def case(id,turns,title,desc,questions=None):
    assert len(turns)%2==1
    messages=[dict(role='system',content=SYSTEM)]+[dict(role='user' if i%2==0 else 'assistant',content=t) for i,t in enumerate(turns)]
    messages.append(dict(role='assistant',content=json.dumps(dict(summary=title,description=desc,questions=questions or []),ensure_ascii=False)))
    return dict(id=id,topic=id,task='draft',source='synthetic',messages=messages)

